<div class="step-indicator">
    @foreach (var (name, index) in StepNames.Select((n, i) => (n, i + 1)))
    {
        var step = index;
        var isCompleted = CompletedSteps.Contains(step);
        var isCurrent = step == CurrentStep;

        <div class="step @(isCurrent ? "current" : isCompleted ? "completed" : "")"
             @onclick="() => OnStepClick(step)"
             style="cursor: @(isCompleted && !isCurrent ? "pointer" : "default")">
            <div class="step-circle">
                @if (isCompleted && !isCurrent)
                {
                    <span>✓</span>
                }
                else
                {
                    <span>@step</span>
                }
            </div>
            <span class="step-label">@name</span>
        </div>

        @if (step < StepNames.Length)
        {
            <div class="step-connector @(isCompleted ? "completed" : "")"></div>
        }
    }
</div>

@code {
    private static readonly string[] StepNames =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = [];
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private async Task OnStepClick(int step)
    {
        if (CompletedSteps.Contains(step) && step != CurrentStep)
        {
            await OnStepClicked.InvokeAsync(step);
        }
    }
}
"}

