{"file_text": "
<h3>Personal Information</h3>

<div class="form-group">
    <label>Full Name <span class="required">*</span></label>
    <input type="text" @bind="Model.FullName" @bind:event="oninput" placeholder="Your full name" />
</div>

<div class="form-group">
    <label>Email <span class="required">*</span></label>
    <input type="email" @bind="Model.Email" @bind:event="oninput" placeholder="you@example.com" />
    @if (!string.IsNullOrEmpty(EmailError))
    {
        <span class="field-error">@EmailError</span>
    }
</div>

<div class="form-row">
    <div class="form-group">
        <label>Phone <span class="required">*</span></label>
        <input type="tel" @bind="Model.Phone" @bind:event="oninput" placeholder="Phone number" />
    </div>
    <div class="form-group">
        <label>Address <span class="required">*</span></label>
        <input type="text" @bind="Model.Address" @bind:event="oninput" placeholder="Your address" />
    </div>
</div>

@if (!string.IsNullOrEmpty(ValidationError))
{
    <div class="validation-error">@ValidationError</div>
}

<div class="step-buttons">
    <div></div>
    <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public string? EmailError { get; set; }

    private string? ValidationError;

    private async Task HandleNext()
    {
        ValidationError = null;

        if (string.IsNullOrWhiteSpace(Model.FullName) ||
            string.IsNullOrWhiteSpace(Model.Email) ||
            string.IsNullOrWhiteSpace(Model.Phone) ||
            string.IsNullOrWhiteSpace(Model.Address))
        {
            ValidationError = "Please fill in all required fields.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}
