@page "/apply"
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h2>Job Application</h2>

    @if (submittedId is not null)
    {
        <div class="confirmation">
            <div class="confirmation-icon">✓</div>
            <h3>Application Submitted!</h3>
            <p>Your application has been received. Your application ID is:</p>
            <div class="application-id">#@submittedId</div>
            <p>Please save this ID for your records.</p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="currentStep"
                       CompletedSteps="completedSteps"
                       OnStepClicked="GoToStep" />

        <div class="step-content">
            @switch (currentStep)
            {
                case 1:
                    <PersonalInfoStep Model="personalInfo"
                                      EmailError="@emailError"
                                      OnNext="HandlePersonalInfoNext" />
                    break;
                case 2:
                    <WorkHistoryStep Entries="workEntries"
                                     OnNext="() => AdvanceStep()"
                                     OnBack="() => GoToStep(currentStep - 1)" />
                    break;
                case 3:
                    <ReferencesStep References="references"
                                    OnNext="() => AdvanceStep()"
                                    OnBack="() => GoToStep(currentStep - 1)" />
                    break;
                case 4:
                    <CoverLetterStep @bind-CoverLetter="coverLetter"
                                     OnNext="() => AdvanceStep()"
                                     OnBack="() => GoToStep(currentStep - 1)" />
                    break;
                case 5:
                    <ReviewStep Personal="personalInfo"
                                WorkEntries="workEntries"
                                References="references"
                                CoverLetter="@coverLetter"
                                IsSubmitting="isSubmitting"
                                SubmitError="@submitError"
                                OnEditSection="GoToStep"
                                OnSubmit="HandleSubmit"
                                OnBack="() => GoToStep(currentStep - 1)" />
                    break;
            }
        </div>
    }
</div>

@code {
    private int currentStep = 1;
    private readonly HashSet<int> completedSteps = [];

    // Form state
    private readonly PersonalInfoModel personalInfo = new();
    private readonly List<WorkEntryModel> workEntries = [new()];
    private readonly List<ReferenceModel> references = [new(), new()];
    private string coverLetter = "";

    // UI state
    private string? emailError;
    private bool isSubmitting;
    private string? submitError;
    private int? submittedId;

    private async Task HandlePersonalInfoNext()
    {
        emailError = null;

        var isValid = await ApplicationService.ValidateEmailAsync(personalInfo.Email);
        if (!isValid)
        {
            emailError = "Please enter a valid email address.";
            return;
        }

        AdvanceStep();
    }

    private void AdvanceStep()
    {
        completedSteps.Add(currentStep);
        if (currentStep < 5)
        {
            currentStep++;
        }
    }

    private void GoToStep(int step)
    {
        if (step >= 1 && step <= 5)
        {
            currentStep = step;
        }
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        submitError = null;

        try
        {
            var application = new JobApplication(
                personalInfo.ToRecord(),
                new WorkHistory(workEntries.Select(e => e.ToRecord()).ToList()),
                references.Select(r => r.ToRecord()).ToList(),
                coverLetter
            );

            var id = await ApplicationService.SubmitApplicationAsync(application);
            submittedId = id;
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

