+}
+
+::deep .btn-remove {
+    background: none;
+    color: #dc2626;
+    border: none;
+    font-size: 0.85rem;
+    cursor: pointer;
+    padding: 0.25rem 0.5rem;
+}
+
+::deep .btn-remove:hover {
+    text-decoration: underline;
+}
+
+::deep .btn-link {
+    background: none;
+    border: none;
+    color: #2563eb;
+    font-size: 0.875rem;
+    cursor: pointer;
+    padding: 0;
+}
+
+::deep .btn-link:hover {
+    text-decoration: underline;
+}
+
+::deep .btn-submit {
+    padding: 0.7rem 2rem;
+    font-size: 1rem;
+}
+
+/* Cover Letter */
+::deep .char-count {
+    font-size: 0.8rem;
+    color: #6b7280;
+    text-align: right;
+    margin-top: 0.25rem;
+}
+
+::deep .char-count.over-limit {
+    color: #dc2626;
+}
+
+/* Review */
+::deep .review-section {
+    border: 1px solid #e5e7eb;
+    border-radius: 8px;
+    padding: 1rem;
+    margin-bottom: 1rem;
+}
+
+::deep .review-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    margin-bottom: 0.75rem;
+}
+
+::deep .review-header h4 {
+    margin: 0;
+    color: #111827;
+}
+
+::deep .review-section dl {
+    display: grid;
+    grid-template-columns: auto 1fr;
+    gap: 0.35rem 1rem;
+    margin: 0;
+    font-size: 0.9rem;
+}
+
+::deep .review-section dt {
+    font-weight: 500;
+    color: #6b7280;
+}
+
+::deep .review-section dd {
+    margin: 0;
+    color: #111827;
+}
+
+::deep .review-entry {
+    padding: 0.5rem 0;
+    font-size: 0.9rem;
+}
+
+::deep .review-entry + .review-entry {
+    border-top: 1px solid #f3f4f6;
+}
+
+::deep .review-detail {
+    font-size: 0.8rem;
+    color: #6b7280;
+    margin-top: 0.15rem;
+}
+
+::deep .review-description {
+    font-size: 0.85rem;
+    color: #4b5563;
+    margin: 0.25rem 0 0;
+}
+
+::deep .review-cover-letter {
+    font-size: 0.9rem;
+    white-space: pre-wrap;
+    color: #374151;
+    margin: 0;
+}
+
+/* Confirmation */
+.confirmation {
+    text-align: center;
+    padding: 3rem 1rem;
+}
+
+.confirmation-icon {
+    width: 64px;
+    height: 64px;
+    border-radius: 50%;
+    background: #16a34a;
+    color: #fff;
+    font-size: 2rem;
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    margin: 0 auto 1rem;
+}
+
+.confirmation h3 {
+    color: #16a34a;
+    margin-bottom: 0.5rem;
+}
+
+.application-id {
+    font-size: 1.5rem;
+    font-weight: 700;
+    color: #2563eb;
+    margin: 1rem 0;
+}
+

